<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Painel de controle · Integração BI</title>
    <style>
        :root{--bg:#07110f;--panel:#0d1c18;--panel2:#10231e;--line:#26483f;--muted:#8ba79f;--text:#edf7f3;--green:#5dd6ad;--amber:#f3bd65;--red:#ff887e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,sans-serif}.layout{min-height:100vh;display:grid;grid-template-columns:240px 1fr}.sidebar{position:sticky;top:0;height:100vh;padding:26px 18px;border-right:1px solid #1e3932;background:#091713}.brand{display:flex;align-items:center;gap:11px;padding:0 8px 28px}.mark{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:#16372e;color:var(--green)}.brand strong{display:block;font-size:14px}.brand small{color:var(--muted);font-size:10px;letter-spacing:.09em;text-transform:uppercase}.nav-label{padding:0 10px;margin:16px 0 7px;color:#5f8177;font-size:10px;text-transform:uppercase;letter-spacing:.13em}.nav-item{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:10px;color:#91aea5;text-decoration:none;font-size:13px}.nav-item.active{background:#153129;color:#eafff7}.nav-item:hover{color:#fff;background:#10251f}.sidebar-foot{position:absolute;left:18px;right:18px;bottom:20px}.who{padding:12px;border:1px solid #203d35;border-radius:12px;margin-bottom:9px;color:#a9c3bb;font-size:12px}.logout{width:100%;padding:10px;border:1px solid #2a4a41;border-radius:10px;background:transparent;color:#a9c3bb;cursor:pointer}.main{min-width:0;padding:34px clamp(22px,4vw,58px) 60px;background-image:radial-gradient(circle at 85% 0,#15382f 0,transparent 25%)}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:30px}h1{margin:0;font-size:28px;letter-spacing:-.045em}.subtitle{margin:7px 0 0;color:var(--muted);font-size:13px}.actions{display:flex;gap:10px}.button{padding:10px 14px;border:1px solid #31574c;border-radius:10px;background:#10231e;color:#d9ebe5;text-decoration:none;font-weight:650;font-size:12px;cursor:pointer}.button.primary{border-color:#4fbd98;background:var(--green);color:#062219}.button:disabled{opacity:.55}.cards{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:12px;margin-bottom:26px}.metric{padding:18px;border:1px solid var(--line);border-radius:15px;background:linear-gradient(145deg,#10231e,#0b1916)}.metric span{display:block;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em}.metric strong{display:block;margin-top:9px;font-size:25px;letter-spacing:-.04em}.section{margin-top:24px}.section-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:12px}.section h2{margin:0;font-size:16px}.section-head p{margin:4px 0 0;color:var(--muted);font-size:12px}.connections{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.connection{padding:17px;border:1px solid var(--line);border-radius:14px;background:var(--panel)}.connection-top{display:flex;justify-content:space-between}.status{display:inline-flex;align-items:center;gap:6px;font-size:11px}.dot{width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 12px var(--green)}.offline .dot{background:var(--red)}.connection strong{font-size:14px}.connection dl{display:grid;grid-template-columns:1fr auto;gap:7px;margin:15px 0 0;color:var(--muted);font-size:11px}.connection dd{margin:0;color:#cce0da}.credentials{display:flex;gap:10px;overflow:auto;padding-bottom:4px}.credential{min-width:260px;padding:15px;border:1px solid var(--line);border-radius:13px;background:var(--panel)}.credential .code{font-weight:800}.credential .url{margin:6px 0;color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#173c31;color:#7ce5bf;font-size:10px}.pill.off{background:#3a211e;color:#ffaaa2}.table-panel{position:relative;border:1px solid var(--line);border-radius:16px;overflow:hidden;background:var(--panel)}.toolbar{display:flex;gap:10px;padding:13px;border-bottom:1px solid var(--line)}.search{flex:1;max-width:360px;padding:10px 12px;border:1px solid #2b5046;border-radius:9px;background:#081612;color:#fff;outline:none}.filter{padding:10px;border:1px solid #2b5046;border-radius:9px;background:#0b1a16;color:#bcd1cb}table{width:100%;border-collapse:collapse}th,td{padding:12px 15px;text-align:left;border-bottom:1px solid #19332c;font-size:12px}th{color:#789a90;font-size:10px;text-transform:uppercase;letter-spacing:.08em}tbody tr:hover{background:#10261f}td.name{color:#dff4ed;font-family:ui-monospace,SFMono-Regular,monospace}.empty{color:var(--amber)}.muted{color:var(--muted)}.footer-time{margin-top:12px;color:#607e75;font-size:11px;text-align:right}.modal-overlay{position:fixed;inset:0;z-index:30;display:grid;place-items:center;padding:18px;background:#0000;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .22s ease,background-color .22s ease,visibility 0s linear .22s}.modal-overlay.open{background:#000a;opacity:1;visibility:visible;pointer-events:auto;transition-delay:0s}.modal{width:min(470px,100%);padding:21px;border:1px solid #31584d;border-radius:15px;background:#0d1c18;box-shadow:0 25px 80px #000;opacity:0;transform:translateY(14px) scale(.97);transition:opacity .22s ease,transform .22s cubic-bezier(.2,.8,.2,1)}.modal-overlay.open .modal{opacity:1;transform:translateY(0) scale(1)}.modal-head{display:flex;align-items:flex-start;justify-content:space-between}.modal h2{margin:0;font-size:17px}.modal p{color:var(--muted);font-size:11px;line-height:1.6}.modal-close{border:0;background:transparent;color:#9bb9b0;font-size:22px;cursor:pointer}.modal label{display:block;margin-top:12px;color:#9cb8b0;font-size:11px}.modal input{display:block;width:100%;margin-top:6px;padding:11px;border:1px solid #31584d;border-radius:9px;background:#081612;color:#fff}.form-error{margin-top:7px;color:#ffaaa2;font-size:11px}.flash{margin-bottom:14px;padding:11px 14px;border:1px solid #34715f;border-radius:10px;background:#123128;color:#8ce8c6;font-size:12px}.toast{position:fixed;right:22px;bottom:22px;padding:12px 15px;border:1px solid #39705f;border-radius:10px;background:#15342b;box-shadow:0 15px 40px #0008;font-size:12px;opacity:0;transform:translateY(10px);pointer-events:none;transition:.2s}.toast.show{opacity:1;transform:none}.table-loading{position:absolute;z-index:8;inset:65px 0 0;display:flex;align-items:flex-start;justify-content:center;padding-top:70px;background:#07110fca;backdrop-filter:blur(2px);opacity:0;visibility:hidden;pointer-events:none;transition:opacity .16s,visibility 0s linear .16s}.table-loading.active{opacity:1;visibility:visible;pointer-events:auto;transition-delay:0s}.table-loading-content{display:flex;align-items:center;gap:11px;padding:12px 16px;border:1px solid #31574c;border-radius:11px;background:#10231e;box-shadow:0 14px 40px #0008;color:#bff8e3;font-size:12px;font-weight:650}.table-spinner{width:17px;height:17px;border:2px solid #5dd6ad40;border-top-color:var(--green);border-radius:50%;animation:spin .7s linear infinite}@media(max-width:1050px){.cards{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.layout{display:block}.sidebar{position:static;width:100%;height:auto;border-right:0;border-bottom:1px solid var(--line)}.sidebar .nav-label,.sidebar .nav-item:not(.active),.sidebar-foot{display:none}.brand{padding-bottom:12px}.main{padding:25px 16px 50px}.top{display:block}.actions{margin-top:18px}.cards{grid-template-columns:repeat(2,1fr)}.connections{grid-template-columns:1fr}.table-panel{overflow:auto}table{min-width:680px}}
        .toolbar .button{margin-left:auto;white-space:nowrap}.sync-badge{display:inline-block;margin-left:8px;padding:3px 7px;border-radius:999px;background:#173c31;color:#7ce5bf;font:9px Inter,ui-sans-serif,system-ui,sans-serif;text-transform:uppercase;letter-spacing:.06em}
        .button.icon{width:38px;height:38px;padding:0;display:grid;place-items:center;border-radius:50%;font-size:20px;line-height:1}.button.icon.loading{animation:spin .8s linear infinite}.button:not(.icon).loading,.filter.loading{border-color:#5dd6ad;color:#bff8e3;box-shadow:0 0 0 1px #5dd6ad33,0 0 22px #5dd6ad1f;animation:updatePulse 1.15s ease-in-out infinite}.button:not(.icon).loading{position:relative;overflow:hidden}.button:not(.icon).loading::after{content:"";position:absolute;inset:0;transform:translateX(-110%);background:linear-gradient(100deg,transparent,#ffffff20,transparent);animation:updateShimmer 1.1s linear infinite}.filter.loading{cursor:wait;opacity:.8}@keyframes updatePulse{50%{background:#17372e}}@keyframes updateShimmer{to{transform:translateX(110%)}}.reload-button{padding:6px 9px;font-size:10px}.reload-state{display:block;margin-top:5px;color:var(--amber);font-size:9px;max-width:240px}.reload-state.failed{color:var(--red)}.credential-submit{margin-top:18px}.credential-head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}.credential-action{margin-top:12px}.initial-progress{height:6px;margin-top:12px;border-radius:999px;background:#19332c;overflow:hidden}.initial-progress i{display:block;height:100%;border-radius:999px;background:var(--green);transition:width .35s}.initial-meta{margin-top:7px;color:var(--muted);font-size:10px}.initial-error{margin-top:7px;color:var(--red);font-size:10px;line-height:1.45}@keyframes spin{to{transform:rotate(360deg)}}
        .credential-tools{display:flex;align-items:center;justify-content:flex-end;gap:10px}.credential-search{width:min(320px,40vw);flex:none}
    </style>
</head>
<body><div class="layout">
    <aside class="sidebar"><div class="brand"><div class="mark">◆</div><div><strong>Integração BI</strong></div></div><div class="nav-label">Visão geral</div><a class="nav-item active" href="{{ route('admin.dashboard') }}">◫ &nbsp; Painel</a><a class="nav-item" href="{{ route('admin.services') }}">◇ &nbsp; Serviços</a><div class="sidebar-foot"><form method="POST" action="{{ route('admin.logout') }}">@csrf<button class="logout">Encerrar sessão</button></form></div></aside>
    <main class="main">@if(session('status'))<div class="flash">{{ session('status') }}</div>@endif<header class="top" style="justify-content:flex-end"><div class="actions"><button class="button primary icon" id="refresh" title="Atualizar" aria-label="Atualizar">↻</button></div></header>
        <section class="cards" id="metrics"><div class="metric"><span>Empresas</span><strong data-metric="companies">{{ $overview['summary']['companies'] }}</strong></div><div class="metric"><span>Credenciais</span><strong data-metric="credentials">{{ $overview['summary']['credentials'] }}</strong></div><div class="metric"><span>Tabelas WebPosto</span><strong data-metric="tables">{{ $overview['summary']['tables'] }}</strong></div><div class="metric"><span>Tokens da API</span><strong data-metric="api_tokens">{{ $overview['summary']['api_tokens'] }}</strong></div></section>
        <section class="section"><div class="section-head"><div><h2>Conexões</h2></div></div><div class="connections" id="connections"></div></section>
        <section class="section"><div class="section-head"><div><h2>WebPosto</h2></div><div class="credential-tools"><input class="search credential-search" id="credential-search" placeholder="Buscar posto por nome ou código..."><select class="filter" id="credential-status-filter" aria-label="Filtrar postos por status de sincronização"><option value="all">Todos os status</option><option value="sincronizado">Sincronizados</option><option value="aguardando_sincronizacao">Não sincronizados</option></select><button class="button primary icon" id="add-credential" type="button" title="Cadastrar token" aria-label="Cadastrar token">+</button></div></div><div class="credentials" id="credentials"></div></section>
        <section class="section"><div class="table-panel"><div class="toolbar"><input class="search" id="search" placeholder="Buscar tabela..."><select class="filter" id="reload-company" aria-label="Empresa para recarga"></select><select class="filter" id="filter"><option value="all">Todas</option><option value="new-records-sync">Dados novos</option><option value="full-reconciliation-sync">Conciliação completa</option></select><button class="button" id="refresh-tables" type="button">&#8635; Atualizar tabelas</button></div><div class="table-loading" id="table-loading" role="status" aria-live="polite"><div class="table-loading-content"><i class="table-spinner"></i><span id="table-loading-text">Carregando dados do posto...</span></div></div><table><thead><tr><th>Tabela</th><th>Registros</th><th>Colunas</th><th>Tamanho</th><th>Última atualização</th><th>Ações</th></tr></thead><tbody id="table-body"></tbody></table></div><div class="footer-time">Atualizado em <span id="generated-at"></span></div></section>
    </main></div><div class="modal-overlay" id="reload-modal"><div class="modal"><div class="modal-head"><div><h2>Confirmar rebase</h2><p id="reload-modal-message"></p></div><button class="modal-close" id="reload-modal-close" type="button">&times;</button></div><div style="display:flex;justify-content:flex-end;gap:10px;margin-top:20px"><button class="button" id="reload-cancel" type="button">Não, cancelar</button><button class="button primary" id="reload-confirm" type="button">Sim, fazer rebase</button></div></div></div><div class="modal-overlay {{ $errors->any() ? 'open' : '' }}" id="credential-modal"><div class="modal"><div class="modal-head"><div><h2>Cadastrar credencial</h2></div><button class="modal-close" id="credential-close" type="button">&times;</button></div><form method="POST" action="{{ route('admin.credentials.store') }}">@csrf<label>URL do WebPosto<input type="url" name="base_url" required value="{{ old('base_url','https://web.qualityautomacao.com.br/') }}"></label>@error('base_url')<div class="form-error">{{ $message }}</div>@enderror<label>Token<input type="password" name="token" required autocomplete="new-password" placeholder="Token fornecido pelo WebPosto"></label>@error('token')<div class="form-error">{{ $message }}</div>@enderror<button class="button primary credential-submit" type="submit">Validar e cadastrar</button></form></div></div><div class="toast" id="toast">Painel atualizado com sucesso.</div>
<script>
const initial=@json($overview);let state=initial;const syncCompanyUrl=@json(route('admin.credentials.synchronize',['empresa'=>'__empresa__']));const fmt=new Intl.NumberFormat('pt-BR');const date=v=>v?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v.replace(' ','T'))):'—';const bytes=v=>v<1024?v+' B':v<1048576?(v/1024).toFixed(1)+' KB':(v/1048576).toFixed(1)+' MB';
function onboardingLabel(c){return c.onboarding_status==="sincronizado"?"Sincronizado":"Não sincronizado"}function renderCredentials(){const q=(document.getElementById('credential-search')?.value||'').trim().toLowerCase();const statusFilter=document.getElementById('credential-status-filter')?.value||'all';const list=state.credentials.filter(c=>(!q||c.empresa_nome.toLowerCase().includes(q)||String(c.empresa_codigo).includes(q))&&(statusFilter==='all'||c.onboarding_status===statusFilter));document.getElementById('credentials').innerHTML=list.length?list.map(credentialCard).join(''):'<span class="muted">Nenhum posto encontrado para esse filtro.</span>'}function credentialCard(c){const run=c.initial_sync;const busy=run&&['queued','running'].includes(run.status);const total=Number(run?.total_resources||0),position=Number(run?.current_position||0),percent=total?Math.min(100,Math.round(position/total*100)):0;const progress=run?`<div class="initial-progress"><i style="width:${run.status==='success'?100:percent}%"></i></div><div class="initial-meta">${run.status==='queued'?'Aguardando na fila':run.status==='running'?'Sincronizando '+esc(run.current_resource||'dados')+' · '+position+'/'+total:run.status==='failed'?'Carga interrompida':run.status==='success'?'Carga inicial concluída':''}</div>${run.error?`<div class="initial-error">${esc(run.error)}</div>`:''}`:'';const action=c.onboarding_status!=='sincronizado'?`<form class="credential-action" method="POST" action="${syncCompanyUrl.replace('__empresa__',c.empresa_codigo)}"><input type="hidden" name="_token" value="${csrf}"><button class="button primary" type="submit" ${busy?'disabled':''}>${busy?'Sincronizando...':run?.status==='failed'?'Tentar novamente':'Sincronizar dados'}</button></form>`:'';return `<article class="credential"><div class="credential-head"><div><div class="code">${esc(c.empresa_nome)}</div><p class="url">Código ${c.empresa_codigo}</p></div><span class="pill ${c.onboarding_status==='sincronizado'?'':'off'}">${onboardingLabel(c)}</span></div>${progress}${action}</article>`}function render(data){state=data;Object.entries(data.summary).forEach(([k,v])=>{const e=document.querySelector(`[data-metric="${k}"]`);if(e)e.textContent=fmt.format(v)});document.getElementById('connections').innerHTML=data.connections.map(c=>`<article class="connection ${c.status==='offline'?'offline':''}"><div class="connection-top"><strong>${c.label}</strong><span class="status"><i class="dot"></i>${c.status==='online'?'Online':'Offline'}</span></div><dl><dt>Banco</dt><dd>${c.database??'—'}</dd><dt>Latência</dt><dd>${c.latency_ms===null?'—':c.latency_ms+' ms'}</dd></dl></article>`).join('');renderCredentials();document.getElementById('generated-at').textContent=date(data.generated_at);renderTables()}
const reloadUrl=@json(route('admin.tables.reload',['table'=>'__table__']));const csrf=@json(csrf_token());const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));function renderTables(){const company=document.getElementById('reload-company');const previous=company.value;const orderedCredentials=[...state.credentials].sort((a,b)=>Number(b.onboarding_status==='sincronizado')-Number(a.onboarding_status==='sincronizado'));company.innerHTML=orderedCredentials.map(c=>`<option value="${c.empresa_codigo}">${esc(c.empresa_nome)} · ${c.empresa_codigo}${c.onboarding_status==='sincronizado'?'':' (não sincronizado)'}</option>`).join('')||'<option value="">Nenhum posto cadastrado</option>';if(previous&&[...company.options].some(o=>o.value===previous))company.value=previous;const empresa=Number(company.value);const q=document.getElementById('search').value.toLowerCase();const f=document.getElementById('filter').value;const rows=state.tables.filter(t=>t.name.toLowerCase().includes(q)&&(f==='all'||(f==='new-records-sync'&&t.new_records_sync)||(f==='full-reconciliation-sync'&&t.full_reconciliation_sync)));document.getElementById('table-body').innerHTML=rows.map(t=>{const allowed=['venda_itens','abastecimentos','bombas','bicos','tanques','cartoes','administradoras','produto_grupos','produto_subgrupos','produtos','produto_empresas','produto_lmc_lmp','lmcs','vales_funcionario','funcionario_funcoes','caixas','caixas_apresentados','planos_conta_gerencial','planos_conta_contabil','contas_bancarias','movimentos_conta','funcionarios','estoque_periodos','fornecedores','compras','compra_itens','titulos_pagar','cliente_grupos','clientes','cliente_empresas','formas_pagamento','pdvs','vendas','venda_formas_pagamento','titulos_receber'].includes(t.name);const run=(state.reloads||[]).find(r=>r.empresa_codigo===empresa&&r.resource===t.name);const busy=run&&['queued','running'].includes(run.status);const labels={queued:'Aguardando',running:'Executando',success:'Concluída',failed:'Falhou'};const action=allowed?`<form method="POST" action="${reloadUrl.replace('__table__',t.name)}" data-reload="${t.name}"><input type="hidden" name="_token" value="${csrf}"><input type="hidden" name="empresa_codigo" value="${empresa}"><button class="button reload-button" type="submit" ${busy||!empresa?'disabled':''}>${busy?'Recarga em andamento':'Recarregar dados'}</button>${run?`<span class="reload-state ${run.status==='failed'?'failed':''}">${labels[run.status]||run.status} · ${date(run.finished_at||run.started_at)}${run.error?' · '+esc(run.error):''}</span>`:''}</form>`:'—';return `<tr><td class="name">${t.name}${allowed?'<span class="sync-badge">Carga validada</span>':''}${t.new_records_sync?'<span class="sync-badge">Dados novos</span>':''}${t.full_reconciliation_sync?'<span class="sync-badge">Conciliação completa</span>':''}</td><td class="${t.records===0?'empty':''}">${fmt.format(t.records)}</td><td>${fmt.format(t.columns)}</td><td>${bytes(t.size_bytes)}</td><td class="muted">${date(t.last_update)}</td><td>${action}</td></tr>`}).join('')||'<tr><td colspan="6" class="muted">Nenhuma tabela encontrada.</td></tr>'}
const companySelect=document.getElementById('reload-company');
const tableLoading=document.getElementById('table-loading');
const tableLoadingText=document.getElementById('table-loading-text');
const refreshButton=document.getElementById('refresh');
const refreshTablesButton=document.getElementById('refresh-tables');
let activeRefreshController=null;
let activeRefreshPromise=null;

function setTableLoading(active,message='Carregando dados do posto...'){
    tableLoadingText.textContent=message;
    tableLoading.classList.toggle('active',active);
    tableLoading.setAttribute('aria-busy',active?'true':'false');
    companySelect.disabled=active;
    document.getElementById('filter').disabled=active;
    refreshTablesButton.disabled=active;
}

function selectedCompany(){
    const value=companySelect.value;
    return value?Number(value):null;
}

function refreshOverview({silent=false,company=selectedCompany(),force=false,tableFeedback=false}={}){
    if(activeRefreshPromise&&!force)return activeRefreshPromise;
    if(force&&activeRefreshController)activeRefreshController.abort();

    const controller=new AbortController();
    const startedAt=Date.now();
    activeRefreshController=controller;
    if(tableFeedback)setTableLoading(true);
    if(!silent){refreshButton.disabled=true;refreshButton.classList.add('loading')}

    const request=(async()=>{
        let failed=false;
        try{
            const overviewUrl=new URL(@json(route('admin.overview')),window.location.origin);
            if(company)overviewUrl.searchParams.set('empresa_codigo',company);
            const response=await fetch(overviewUrl,{headers:{Accept:'application/json'},cache:'no-store',signal:controller.signal});
            if(!response.ok)throw new Error('Falha ao atualizar o painel.');
            const data=await response.json();
            if(controller.signal.aborted)return false;
            render(data);
            if(!silent){const toast=document.getElementById('toast');toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}
            return true;
        }catch(error){
            if(error.name==='AbortError')return false;
            failed=true;
            if(tableFeedback)setTableLoading(true,'Não foi possível carregar os dados do posto.');
            else if(!silent)alert('Não foi possível atualizar o painel. Verifique sua sessão e as conexões.');
            return false;
        }finally{
            if(activeRefreshController===controller){
                const minimum=tableFeedback?500:0;
                const remaining=Math.max(0,minimum-(Date.now()-startedAt));
                if(remaining)await new Promise(resolve=>setTimeout(resolve,remaining));
                if(failed&&tableFeedback)await new Promise(resolve=>setTimeout(resolve,1300));
                activeRefreshController=null;
                activeRefreshPromise=null;
                if(tableFeedback)setTableLoading(false);
                if(!silent){refreshButton.disabled=false;refreshButton.classList.remove('loading')}
            }
        }
    })();
    activeRefreshPromise=request;
    return request;
}

document.getElementById('search').addEventListener('input',renderTables);
document.getElementById('filter').addEventListener('change',renderTables);
document.getElementById('credential-search').addEventListener('input',renderCredentials);
document.getElementById('credential-status-filter').addEventListener('change',renderCredentials);
refreshButton.addEventListener('click',()=>refreshOverview({force:true,tableFeedback:true}));
