const reloadModal=document.getElementById('reload-modal'),reloadMessage=document.getElementById('reload-modal-message'),reloadConfirm=document.getElementById('reload-confirm');let pendingReload=null;const closeReload=()=>{reloadModal.classList.remove('open');pendingReload=null;reloadConfirm.disabled=false};document.getElementById('table-body').addEventListener('submit',e=>{const form=e.target.closest('[data-reload]');if(!form)return;e.preventDefault();const table=form.dataset.reload,company=document.getElementById('reload-company').selectedOptions[0]?.textContent||'empresa selecionada';const effects={venda_itens:'venda_itens e abastecimentos',abastecimentos:'abastecimentos',bombas:'bombas e bicos',bicos:'bicos',tanques:'tanques e bicos',cartoes:'cartoes',administradoras:'administradoras e cartões',produto_grupos:'grupos de produtos',produto_subgrupos:'subgrupos de produtos',produtos:'produtos',produto_empresas:'produtos por empresa',produto_lmc_lmp:'produtos LMC/LMP',lmcs:'livros de movimentacao de combustiveis',vales_funcionario:'vales de funcionarios',funcionario_funcoes:'funcoes de funcionarios',caixas:'caixas e caixas apresentados',caixas_apresentados:'caixas apresentados',planos_conta_gerencial:'planos de conta gerenciais',planos_conta_contabil:'planos de conta contabeis',contas_bancarias:'contas bancarias e movimentos de conta',movimentos_conta:'movimentos de conta',funcionarios:'funcionarios',estoque_periodos:'estoque por periodo',fornecedores:'fornecedores',compras:'compras',compra_itens:'itens de compra',titulos_pagar:'títulos a pagar',cliente_grupos:'grupos de clientes',clientes:'clientes e vínculos de empresa',cliente_empresas:'vínculos de clientes com empresas',formas_pagamento:'formas de pagamento',pdvs:'pontos de venda',vendas:'vendas, formas de pagamento, itens, abastecimentos e cartões',venda_formas_pagamento:'formas de pagamento das vendas',titulos_receber:'títulos a receber'};reloadMessage.textContent='Esta operação removerá os registros atuais e reconstruirá '+(effects[table]||table)+' para '+company+'. Deseja realmente continuar?';pendingReload=form;reloadModal.classList.add('open')});document.getElementById('reload-cancel').onclick=closeReload;document.getElementById('reload-modal-close').onclick=closeReload;reloadModal.addEventListener('click',e=>{if(e.target===reloadModal)closeReload()});reloadConfirm.onclick=()=>{if(!pendingReload)return;reloadConfirm.disabled=true;reloadConfirm.textContent='Enviando...';pendingReload.submit()};const credentialModal=document.getElementById('credential-modal');const closeCredential=()=>credentialModal.classList.remove('open');document.getElementById('add-credential').onclick=()=>credentialModal.classList.add('open');document.getElementById('credential-close').onclick=closeCredential;credentialModal.addEventListener('click',e=>{if(e.target===credentialModal)closeCredential()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCredential()});
